import {
  Timeline,
  TimelineContent,
  TimelineHeader,
  TimelineIndicator,
  TimelineItem,
  TimelineSeparator,
  TimelineTitle,
} from '@/registry/ndeko/ui/timeline';

import { AgoTime } from './_parts/ago-time';
import { currentStepOf, stepStateOf, StepStateNote } from './_parts/step-state';

type ReviewStep = {
  title: string;
  detail: string;
  at?: string;
};

const REVIEW: ReviewStep[] = [
  {
    title: 'Pull request opened',
    detail: 'Mira opened #418, which keeps cart totals in whole cents.',
    at: '2026-11-12T14:18:00',
  },
  {
    title: 'Checks finished',
    detail: 'Type check, lint and 212 tests ran on the first push.',
    at: '2026-11-12T14:25:00',
  },
  {
    title: 'Changes requested',
    detail: 'Idris asked for a rounding test on carts that mix two currencies.',
    at: '2026-11-12T14:42:00',
  },
  {
    title: 'Fix pushed',
    detail:
      'One commit adds the rounding test. The pull request waits for a second look.',
  },
];

const DONE_COUNT = 3;

export default function Timeline04() {
  return (
    <Timeline
      defaultValue={DONE_COUNT}
      role='list'
      aria-label='Review of pull request 418'
    >
      {REVIEW.map((reviewStep, index) => {
        const step = index + 1;
        const state = stepStateOf(step, DONE_COUNT);

        return (
          <TimelineItem
            key={reviewStep.title}
            step={step}
            role='listitem'
            aria-current={currentStepOf(state)}
          >
            <TimelineHeader>
              <TimelineIndicator />
              <TimelineSeparator />
              <TimelineTitle className='-mt-0.5'>
                {reviewStep.title}
                <StepStateNote state={state} />
              </TimelineTitle>
            </TimelineHeader>
            <TimelineContent>
              {reviewStep.detail}
              {reviewStep.at && <AgoTime at={reviewStep.at} className='mt-2' />}
            </TimelineContent>
          </TimelineItem>
        );
      })}
    </Timeline>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { TimelineDate } from '@/registry/ndeko/ui/timeline';

import { agoLabelOf, stampLabelOf } from './dates';

type AgoTimeProps = {
  at: string;
  className?: string;
};

export function AgoTime({ at, className }: AgoTimeProps) {
  return (
    <TimelineDate
      dateTime={at}
      title={stampLabelOf(at)}
      className={cn('mb-0', className)}
    >
      {agoLabelOf(at)}
    </TimelineDate>
  );
}

import { differenceInMinutes, format, parseISO } from 'date-fns';

/* Every time is read against one fixed moment and written without a time zone, so the server and the browser print the same labels. */
const NOW = '2026-11-12T15:00:00';

const MINUTES_PER_HOUR = 60;

const MINUTES_PER_DAY = 1440;

export function dayLabelOf(isoDay: string) {
  const day = parseISO(isoDay);
  return format(day, 'MMM d, yyyy');
}

export function stampLabelOf(isoTime: string) {
  const time = parseISO(isoTime);
  return format(time, "MMMM d, yyyy 'at' HH:mm");
}

function agoOf(count: number, unit: string) {
  if (count === 1) {
    return `1 ${unit} ago`;
  }
  return `${count} ${unit}s ago`;
}

export function agoLabelOf(isoTime: string) {
  const now = parseISO(NOW);
  const time = parseISO(isoTime);
  const minutes = differenceInMinutes(now, time);
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return agoOf(minutes, 'minute');
  }
  if (minutes < MINUTES_PER_DAY) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return agoOf(hours, 'hour');
  }
  const days = Math.floor(minutes / MINUTES_PER_DAY);
  return agoOf(days, 'day');
}

type StepState = 'done' | 'current' | 'ahead';

const STATE_WORD: Record<StepState, string> = {
  done: 'done',
  current: 'in progress',
  ahead: 'to come',
};

export function stepStateOf(step: number, doneCount: number): StepState {
  if (step <= doneCount) {
    return 'done';
  }
  if (step === doneCount + 1) {
    return 'current';
  }
  return 'ahead';
}

export function currentStepOf(state: StepState) {
  if (state === 'current') {
    return 'step' as const;
  }
  return undefined;
}

type StepStateNoteProps = {
  state: StepState;
};

/* The colour of the marker says where a step stands: this says it in words for a screen reader. */
export function StepStateNote({ state }: StepStateNoteProps) {
  return <span className='sr-only'>, {STATE_WORD[state]}</span>;
}
